create function public.final_assert(ok boolean, message text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'TEST009: %',message;end if;end$$;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
create table public.final_fixture(w uuid,c uuid,s uuid,claim jsonb);
insert into public.final_fixture(w,c) select public.create_workspace('Final','final','{"projects":[{"id":"p1","name":"P"}],"tasks":[{"id":"t1","project":"p1","title":"T","recur":"Daily","due":"2026-10-21","labels":["l1"],"subtasks":[{"id":"s1","title":"S"}]}]}'),'10000000-0000-0000-0000-000000000001';
select public.migrate_workspace(w,0) from public.final_fixture;
insert into public.workspace_memberships select w,'00000000-0000-0000-0000-000000000003','member' from public.final_fixture;
insert into auth.oauth_clients select c,'Fixture receiver',null from public.final_fixture;
insert into auth.oauth_consents select '00000000-0000-0000-0000-000000000001',c,null from public.final_fixture;
insert into public.integration_connections(id,user_id,client_id,client_name,status,authorization_id) select c,'00000000-0000-0000-0000-000000000001',c,'Fixture','active','fixture' from public.final_fixture;
insert into public.agents(workspace_id,id,name,auth_user_id,client_id) select w,'receiver','Receiver','00000000-0000-0000-0000-000000000001',c::text from public.final_fixture;
insert into public.agents(workspace_id,id,name,auth_user_id) select w,'runner','Runner','00000000-0000-0000-0000-000000000003' from public.final_fixture;
insert into public.integration_grants select c,w,'write','receiver' from public.final_fixture;
update public.final_fixture set s=public.provision_webhook_subscription(w,c,'00000000-0000-0000-0000-000000000001','https://example.test/hook',repeat('isolated-fixture-',3));
select public.configure_webhook_subscription(w,s,true,array['task.run_blocked'],false) from public.final_fixture;
select public.execute_operation(w,'add_task_comment','{"id":"instruction","taskId":"t1","body":"Exact human instruction"}','comment') is not null from public.final_fixture;
select public.final_assert(public.read_operation(w,'get_task','{"id":"t1","context":"comments","limit":1}')->'context'->'items'->0->>'body'='Exact human instruction','current instructions') from public.final_fixture;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',false);
update public.final_fixture set claim=public.execute_operation(w,'claim_task','{"id":"t1"}','claim',1)->'data';
select public.execute_operation(w,'renew_task_claim',jsonb_build_object('id','t1','claimToken',claim->>'claimToken','executionState','blocked','blockingReason','Need decision'),'blocked',2) is not null from public.final_fixture;
select public.execute_operation(w,'renew_task_claim',jsonb_build_object('id','t1','claimToken',claim->>'claimToken','executionState','blocked','blockingReason','Need decision'),'blocked',2) is not null from public.final_fixture;
select public.final_assert((select count(*)=1 from public.webhook_deliveries),'one durable blocked delivery');
select public.final_assert((select count(*)=1 from pgmq.q_webhook_delivery),'one logged message');
select public.final_assert((select raw_body::jsonb->>'event_type'='task.run_blocked' and raw_body not like '%Need decision%' and raw_body not like '%claimToken%' from public.webhook_deliveries),'minimal blocked payload');
select public.final_assert(public.read_operation(w,'get_task','{"id":"t1"}')->'data'->'execution'->>'reason'='Need decision','blocked read') from public.final_fixture;
select public.execute_operation(w,'renew_task_claim',jsonb_build_object('id','t1','claimToken',claim->>'claimToken'),'renew',3) is not null from public.final_fixture;
select public.final_assert((select count(*)=1 from public.webhook_deliveries),'ordinary renewal does not reemit block');
update public.task_claims set expires_at=clock_timestamp()-interval '1 second';
select public.final_assert((public.read_operation(w,'get_task','{"id":"t1"}')->'data'->'execution'->>'active')::boolean=false,'expired execution inactive') from public.final_fixture;
do $$begin begin perform public.execute_operation(w,'renew_task_claim',jsonb_build_object('id','t1','claimToken',claim->>'claimToken','executionState','blocked','blockingReason','Stale'),'stale',4) from public.final_fixture;raise exception 'stale allowed';exception when sqlstate 'PT409' then null;end;end$$;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select public.execute_operation(w,'intervene_task','{"id":"t1","action":"complete"}','human-complete',4) is not null from public.final_fixture;
select public.final_assert((select execution_state is null and status='done' from public.tasks where id='t1'),'human clears execution');
select public.final_assert((select count(*)=2 from public.tasks),'recurrence child');
select public.final_assert((select count(*)=2 from public.task_labels),'recurrence labels');
select public.execute_operation(w,'create_calendar_event','{"id":"cal","taskId":"t1","title":"Calendar"}','calendar') is not null from public.final_fixture;
insert into public.notifications(workspace_id,id,task_id,notification_type) select w,'note','t1','comment' from public.final_fixture;
select public.execute_operation(w,'intervene_task','{"id":"t1","action":"delete"}','human-delete',5) is not null from public.final_fixture;
select public.final_assert(not exists(select 1 from public.calendar_events where id='cal'),'calendar cascade');
select public.final_assert(not exists(select 1 from public.notifications where id='note'),'notification cascade');
select public.final_assert(not exists(select 1 from public.comments where task_id='t1'),'comment cascade');
select public.final_assert(not exists(select 1 from public.subtasks where task_id='t1'),'subtask cascade');
select public.final_assert(not exists(select 1 from public.task_labels where task_id='t1'),'label cascade');
select 'TEST009 bounded PostgreSQL assertions passed';
